<?php

use Modules\Core\Models\User;use Modules\ProductDev\Models\CostSheet;use Modules\ProductDev\Services\BomService;use Modules\Production\Services\ProductionOrderService;use Modules\Production\Services\StandardCostSnapshotService;
it('cost sheet versi baru tidak mengubah snapshot MO lama',function(){[$u,,,,,,$mo]=shopFixture();$before=$mo->standard_cost_snapshot;$hash=$mo->standard_cost_snapshot_hash;CostSheet::create(['company_id'=>1,'doc_no'=>'COST-NEW-'.uniqid(),'style_id'=>$mo->style_id,'bom_version_id'=>$mo->bom_version_id,'routing_version_id'=>$mo->routing_version_id,'version'=>2,'fabric_cost'=>999,'trim_cost'=>999,'cm_cost'=>999,'overhead_cost'=>999,'fob_price'=>5000,'status'=>'APPROVED','created_by'=>$u->id]);$checked=app(StandardCostSnapshotService::class)->forCosting($mo->fresh());expect($checked->standard_cost_snapshot)->toBe($before)->and($checked->standard_cost_snapshot_hash)->toBe($hash)->and($checked->standard_cost_snapshot['version'])->toBe(1);});
it('snapshot MO tidak dapat diubah setelah terbentuk',function(){[,,,,,,$mo]=shopFixture();$copy=$mo->standard_cost_snapshot;$copy['fabric']=999;$mo->update(['standard_cost_snapshot'=>$copy]);})->throws(LogicException::class,'immutable');
it('release snapshot menolak cost sheet dari BOM version berbeda',function(){$u=User::factory()->create(['company_id'=>1]);[$style,$fabric,$uom]=erpApprovedStyle($u);$bs=app(BomService::class);$next=$bs->createVersion($style->id,[['material_id'=>$fabric->id,'qty_per_pcs'=>3,'uom_id'=>$uom->id]],$u);$bs->markApproved($next);[$so]=erpConfirmedSo($u,$style,10,20);$mo=app(ProductionOrderService::class)->createFromSalesOrder($so,$u)[0];expect($mo->standard_cost_snapshot_hash)->toBeNull();app(StandardCostSnapshotService::class)->requireForRelease($mo);})->throws(RuntimeException::class,'BOM dan routing snapshot yang sama');
